cat > verification/check.py <<'PY'
from pathlib import Path
from decimal import Decimal, ROUND_HALF_UP
import subprocess

root = Path(__file__).resolve().parent.parent
out = root / 'verification'
for name in ('shokugyo_report', 'shokugyo_gaiyou', 'sib_report', 'sib_gaiyou'):
    subprocess.run(['pdftotext', '-layout', str(root / (name + '.pdf')), str(out / (name + '.txt'))], check=True)

def pct(n, d):
    return Decimal(n) * 100 / Decimal(d)

def rounded(x, places='0.1'):
    return x.quantize(Decimal(places), rounding=ROUND_HALF_UP)

lines = []
for n,d in [(79,139),(79,120),(1,29),(2,29),(33,379)]:
    x = pct(n,d)
    lines.append(f'{n}/{d}*100 = {x:.12f}%; round(1dp) = {rounded(x)}%')
for d,target,places in [(29,'5','1'),(29,'5.0','0.1'),(379,'8.7','0.1')]:
    hits = [n for n in range(d+1) if rounded(pct(n,d),places) == Decimal(target)]
    lines.append(f'denominator={d}; rounded target={target}%; matching integer numerators={hits}')
lines.append(f'5/8.7*100 = {Decimal(5)/Decimal(\"8.7\")*100:.12f}%')
(out / 'calculations.txt').write_text('\\n'.join(lines)+'\\n')

selected = {'shokugyo_report':[1,2,3,4,5], 'shokugyo_gaiyou':[1],
            'sib_report':[7,8,11,14,15,16,17,25,26], 'sib_gaiyou':[1]}
with (out / 'excerpts.txt').open('w') as f:
    for name,pages in selected.items():
        text = (out / (name+'.txt')).read_text().split('\\f')
        for p in pages:
            f.write(f'\\n===== {name}.pdf / PDF page {p} =====\\n{text[p-1]}')
print((out/'calculations.txt').read_text())
